-- =====================================================================
-- Helper Academy — v15: dialogs (conversation audio/video) next to songs, linked to one or more units
-- Run AFTER supabase_v14_unit0.sql (safe to run more than once).
-- =====================================================================
alter table public.set_songs add column if not exists kind text not null default 'song';
alter table public.set_songs drop constraint if exists set_songs_kind_check;
alter table public.set_songs add constraint set_songs_kind_check check (kind in ('song','dialog'));
alter table public.set_songs add column if not exists also_units int[] not null default '{}';

-- Copies keep kind and extra units too.
create or replace function public.copy_set(p_set uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare s study_sets%rowtype; nid uuid; inst uuid; t record; ntid uuid;
begin
  if not exists (select 1 from profiles where id = auth.uid() and role = 'teacher') then raise exception 'Only teachers can copy sets'; end if;
  if not can_view_set(p_set) then raise exception 'Set not found'; end if;
  select * into s from study_sets where id = p_set;
  select institution_id into inst from profiles where id = auth.uid();
  insert into study_sets (owner_id, institution_id, subject_id, level_code, curriculum_id, title, description, language, translation_lang, units, visibility)
  values (auth.uid(), inst, s.subject_id, s.level_code, s.curriculum_id, left('Copy of ' || s.title, 120), s.description, s.language, s.translation_lang, s.units, 'private')
  returning id into nid;
  insert into set_items (set_id, position, kind, unit, also_units, term, meaning, example, translation, syllables, image_url, anim_url, audio_url, choices, answer, pronunciation, sound_hint, video_url, emoji)
  select nid, position, kind, unit, also_units, term, meaning, example, translation, syllables, image_url, anim_url, audio_url, choices, answer, pronunciation, sound_hint, video_url, emoji
  from set_items where set_id = p_set;
  for t in select * from set_texts where set_id = p_set loop
    insert into set_texts (set_id, unit, title, body, position) values (nid, t.unit, t.title, t.body, t.position) returning id into ntid;
    insert into set_songs (set_id, text_id, unit, also_units, kind, title, media_url, lines, position)
    select nid, ntid, unit, also_units, kind, title, media_url, lines, position from set_songs where set_id = p_set and text_id = t.id;
  end loop;
  insert into set_songs (set_id, text_id, unit, also_units, kind, title, media_url, lines, position)
  select nid, null, unit, also_units, kind, title, media_url, lines, position from set_songs where set_id = p_set and text_id is null;
  return nid;
end $$;

-- Grade 5 set: the "How Stories Make Vocabulary Stick" dialog (Units 1, 2 and 3).
insert into public.set_songs (id, set_id, text_id, unit, also_units, kind, title, media_url, lines, position)
values ('00000000-0000-4000-8000-00000000d101', '00000000-0000-4000-8000-000000000005', null, 1, '{2,3}', 'dialog',
  'How Stories Make Vocabulary Stick', 'assets/podcasts/how-stories-make-vocabulary-stick.mp4?v=20261122', '[{"t": 0.22, "e": 9.52, "l": "So, um, what do a medieval execution, a superhero''s secret identity, and, like, a crab completely disguised as a garden bug all have in common?", "sp": 2}, {"t": 10.1, "e": 14.08, "l": "I mean, that sounds like a joke setup, but it''s really about how we look at language.", "sp": 1}, {"t": 14.18, "e": 19.26, "l": "Right. They are all hiding in plain sight inside the words we use every single day.", "sp": 2}, {"t": 19.74, "e": 25.22, "l": "We usually... Uh, we treat vocabulary like this chore, you know, just a list of things to memorize for a test.", "sp": 1}, {"t": 25.32, "e": 26.14, "l": "Yeah, totally.", "sp": 2}, {"t": 26.52, "e": 30.04, "l": "But every single word is actually a tiny compressed story.", "sp": 1}, {"t": 30.46, "e": 36.98, "l": "And if you can unlock that story, you don''t just become a better reader, you start seeing the world in, like, higher definition.", "sp": 2}, {"t": 37.44, "e": 38.0, "l": "Absolutely.", "sp": 1}, {"t": 38.44, "e": 49.52, "l": "That is exactly our mission today. So if you are a fifth grader out there listening or, honestly, a curious learner of any age who wants to completely upgrade how you write and speak, this deep dive is for you.", "sp": 2}, {"t": 50.1, "e": 56.9, "l": "We are pulling from a grade five ELA master worksheet, and its multiple choice answer key from Al Hayya International School.", "sp": 1}, {"t": 57.36, "e": 59.72, "l": "But we are absolutely not just gonna read you a dictionary.", "sp": 2}, {"t": 59.8, "e": 65.72, "l": "No, no. The brilliant thing about this source material is that it weaves vocabulary into these distinct mini stories.", "sp": 1}, {"t": 65.82, "e": 66.38, "l": "It''s so cool.", "sp": 2}, {"t": 66.68, "e": 69.64, "l": "Yeah, and it gives us multiple angles to understand every single word.", "sp": 1}, {"t": 69.96, "e": 75.24, "l": "Right. So to really make the word stick, for every word we explore today, we''re gonna look at two or three different examples.", "sp": 2}, {"t": 75.78, "e": 81.36, "l": "We''ll see how it lives in a provided sentence, how the multiple choice questions test its context and-", "sp": 1}, {"t": 81.6, "e": 85.44, "l": "Oh, and those incredibly vivid visual clues from the worksheet''s photo credits.", "sp": 2}, {"t": 85.6, "e": 86.42, "l": "Those are my favorite part.", "sp": 1}, {"t": 86.76, "e": 99.94, "l": "Same. And we''re gonna follow a single thread today. We''ll travel from an ancient Chinese palace, down into the damp dirt with some crustacean bugs, into the secret life of a poet, and finally, to this shadowy moonlit farm.", "sp": 2}, {"t": 100.56, "e": 102.12, "l": "So let''s start right in that palace.", "sp": 1}, {"t": 102.28, "e": 102.7, "l": "Let''s do it.", "sp": 2}, {"t": 102.92, "e": 108.2, "l": "The setting is thousands of years ago, and we have a ruler who is just in terrible shape.", "sp": 1}, {"t": 108.58, "e": 111.64, "l": "We''re looking at our first two words here, lethargic and ailing.", "sp": 2}, {"t": 112.16, "e": 115.92, "l": "Right. The worksheet drops us right into the scene with this sentence.", "sp": 1}, {"t": 116.3, "e": 126.1, "l": "It says, uh, \"The exhausted Chinese Emperor Shen Nong felt extremely lethargic after days without proper sleep, so the royal doctor visited the ailing sovereign.\"", "sp": 2}, {"t": 126.56, "e": 131.42, "l": "Let''s look at the mechanics of those two words because they describe two very different types of misery.", "sp": 1}, {"t": 131.64, "e": 132.64, "l": "Okay, lay it on me.", "sp": 2}, {"t": 133.3, "e": 136.68, "l": "So ailing means suffering from physical illness or poor health.", "sp": 1}, {"t": 136.8, "e": 136.9, "l": "Right.", "sp": 2}, {"t": 137.28, "e": 144.82, "l": "But lethargic is specifically about an unnatural heavy lack of energy. You aren''t just tired, you are physically weighed down.", "sp": 1}, {"t": 145.12, "e": 153.86, "l": "The multiple choice section actually drills this in. Question one reinforces lethargic as being, quote, \"lacking energy, tired, and slow.\"", "sp": 2}, {"t": 154.54, "e": 158.78, "l": "And then the worksheet gives us these photo clues that just make you feel it in your bones.", "sp": 1}, {"t": 158.94, "e": 165.72, "l": "Oh, man. Yeah. For lethargic, there is this image of a yawning infant who literally cannot keep their eyes open.", "sp": 2}, {"t": 166.08, "e": 166.86, "l": "We''ve all been there.", "sp": 1}, {"t": 167.18, "e": 174.22, "l": "Seriously. And for ailing, there''s a photo of a miserable looking child in bed, and they''re taking this nasty castor oil medicine.", "sp": 2}, {"t": 175.14, "e": 177.84, "l": "You just look at that kid and know exactly what ailing means.", "sp": 2}, {"t": 178.44, "e": 186.54, "l": "Which is why the royal doctor is there. He has a solution, but it brings us to our next three words: unpalatable, insisted, and behead.", "sp": 1}, {"t": 187.16, "e": 189.18, "l": "The stakes in this story are wild.", "sp": 2}, {"t": 189.22, "e": 189.86, "l": "They really are.", "sp": 1}, {"t": 190.28, "e": 200.52, "l": "The sentence says, \"The doctor prepared a bitter medicine that was unpalatable, but he insisted the emperor drink it, even though the angry monarch threatened to behead servants bringing bad news.\"", "sp": 2}, {"t": 201.1, "e": 202.82, "l": "That is a very tense medical visit.", "sp": 1}, {"t": 203.08, "e": 205.74, "l": "Yeah, no kidding. Let''s start with unpalatable.", "sp": 2}, {"t": 206.5, "e": 215.22, "l": "So the roof of your mouth is called your palate. It''s where you experience taste. So if something is unpalatable, it is literally rejected by your sense of taste.", "sp": 1}, {"t": 215.36, "e": 217.02, "l": "It is profoundly distasteful.", "sp": 1}, {"t": 217.52, "e": 222.34, "l": "I instantly think of, like, the absolute worst flavor of liquid cherry cough syrup you can imagine.", "sp": 2}, {"t": 222.46, "e": 222.78, "l": "Yes.", "sp": 1}, {"t": 223.38, "e": 232.28, "l": "Question three reminds us the concoction was, quote, \"bitter and unpalatable,\" and the visual clue is this guy in a red knit cap just frowning with utter disgust.", "sp": 2}, {"t": 232.66, "e": 234.94, "l": "Right. But the doctor insisted.", "sp": 1}, {"t": 235.3, "e": 236.0, "l": "He didn''t back down.", "sp": 2}, {"t": 236.36, "e": 245.34, "l": "Exactly. To insist means to demand something firmly, not accepting any refusal. The photo for this is a stern man pointing his finger directly at the camera.", "sp": 1}, {"t": 245.74, "e": 246.6, "l": "He is not asking.", "sp": 1}, {"t": 246.84, "e": 249.9, "l": "He''s telling, even though the emperor wants to behead him.", "sp": 2}, {"t": 250.32, "e": 255.22, "l": "Which if we look at the word is pretty literal, behead. You are separating the head from the body.", "sp": 1}, {"t": 255.56, "e": 258.72, "l": "The photo clue for that one is just a straight up medieval sword.", "sp": 2}, {"t": 259.16, "e": 262.06, "l": "But, uh, before anyone loses their head, the story shifts.", "sp": 1}, {"t": 262.34, "e": 262.82, "l": "Thank goodness.", "sp": 2}, {"t": 262.98, "e": 272.64, "l": "The doctor is insisting, the emperor is refusing, and then a breeze blows through the window. This brings us to aroma, fantastic, and exhilaration.", "sp": 1}, {"t": 273.26, "e": 282.5, "l": "The magical twist. The sentence reads, \"Wild leaves blew into boiling water, creating a rich aroma, a fantastic taste, and a surge of exhilaration.\"", "sp": 2}, {"t": 283.24, "e": 288.72, "l": "So an aroma isn''t just any smell. It''s specifically a pleasant, distinctive fragrance.", "sp": 1}, {"t": 288.82, "e": 290.26, "l": "And question five tests this, right?", "sp": 2}, {"t": 290.6, "e": 293.56, "l": "Exactly. It pairs aroma with pleasant and soothing.", "sp": 1}, {"t": 294.2, "e": 298.18, "l": "And the visual clue of steaming morning tea captures that perfectly.", "sp": 2}, {"t": 298.64, "e": 303.88, "l": "And fantastic, which means extraordinarily good, is paired with a photo of bursting fireworks.", "sp": 1}, {"t": 304.1, "e": 309.72, "l": "Right. But what about exhilaration? Question seven links it to surging with energy.", "sp": 2}, {"t": 310.36, "e": 311.02, "l": "Let me ask you this.", "sp": 1}, {"t": 311.14, "e": 311.28, "l": "Mm-hmm.", "sp": 2}, {"t": 311.4, "e": 318.18, "l": "Is that like, you know when you''re playing a video game, your health bar is blinking red, you''re about to lose, and suddenly you find a secret energy potion?", "sp": 1}, {"t": 318.88, "e": 320.38, "l": "That is precisely the feeling.", "sp": 2}, {"t": 320.9, "e": 321.22, "l": "Nice.", "sp": 1}, {"t": 322.08, "e": 331.74, "l": "I- If you look at the root of exhilaration, it actually shares DNA with the word hilarious. It means to make cheerful, to fill with this wild, joyful energy.", "sp": 2}, {"t": 332.22, "e": 332.74, "l": "Oh, wow.", "sp": 1}, {"t": 333.1, "e": 333.96, "l": "I never put that together.", "sp": 2}, {"t": 334.3, "e": 342.68, "l": "The photo clue they use is a group of junior high school students cheering wildly. You go from lethargic, heavy, and tired to feeling this rushing surge of exhilaration.", "sp": 1}, {"t": 342.92, "e": 345.96, "l": "And just like that, according to the legend, the emperor discovers tea.", "sp": 2}, {"t": 346.3, "e": 354.72, "l": "Yep. But here is where our story travels. Imagine the emperor is drinking his fantastic new beverage, but outside the wind is still blowing.", "sp": 1}, {"t": 355.76, "e": 356.54, "l": "Okay, I''m picturing it.", "sp": 2}, {"t": 357.56, "e": 363.16, "l": "The wild tea leaves that missed his boiling pot flutter through the air and land on the damp ground outside the palace.", "sp": 1}, {"t": 363.84, "e": 366.06, "l": "They start to decay, becoming part of the dirt.", "sp": 1}, {"t": 366.76, "e": 372.12, "l": "Which brings us directly into the domain of our next section, the secret life of the soil.", "sp": 2}, {"t": 372.94, "e": 375.28, "l": "We''re shifting from royal history to biology now.", "sp": 1}, {"t": 375.66, "e": 386.26, "l": "Yeah, starting with the words reside and organism. The worksheet sentence says, \"Roly-poly pill bugs reside in damp soil, and every tiny organism helps the ecosystem.\"", "sp": 2}, {"t": 387.4, "e": 393.54, "l": "Let''s look at reside. It''s stronger than just saying you live somewhere. The root comes from Latin meaning to sit down or settle.", "sp": 1}, {"t": 393.68, "e": 396.64, "l": "When you reside somewhere, you are permanently settled.", "sp": 1}, {"t": 397.26, "e": 397.98, "l": "You belong there.", "sp": 2}, {"t": 398.92, "e": 399.44, "l": "Exactly.", "sp": 1}, {"t": 400.18, "e": 405.14, "l": "The photo clue for reside shows these little bugs crawling over an edge, just really dug into their habitat.", "sp": 2}, {"t": 405.48, "e": 417.66, "l": "And for organism, the worksheet shows a close-up of earthworms in the dirt. Multiple choice question twenty-eight clarifies that an organism is specifically a living entity, contrasting it with something abstract like an idea.", "sp": 1}, {"t": 418.44, "e": 421.52, "l": "Basically, if it breathes, grows, or eats, it''s an organism.", "sp": 2}, {"t": 421.74, "e": 430.2, "l": "Right. But what kind of organism is that pill bug? And this brings us to two of my favorite words on the worksheet, appearance and species.", "sp": 1}, {"t": 431.16, "e": 436.28, "l": "Okay, the sentence is, \"Despite their insect-like appearance, they are actually crustacean species.\"", "sp": 2}, {"t": 437.1, "e": 444.12, "l": "So appearance is the way something looks on the outside, but a species is its actual biological classification, what it truly is.", "sp": 1}, {"t": 444.62, "e": 445.96, "l": "Wait, wait. Let me push back on this a second.", "sp": 2}, {"t": 446.16, "e": 446.3, "l": "Sure.", "sp": 1}, {"t": 447.06, "e": 454.12, "l": "So if their appearance is basically a disguise, does that mean having an insect-like appearance doesn''t actually make you an insect?", "sp": 2}, {"t": 454.38, "e": 456.36, "l": "Are pill bugs basically tiny land crabs?", "sp": 2}, {"t": 456.66, "e": 458.98, "l": "They absolutely are. They''re isopods.", "sp": 1}, {"t": 459.62, "e": 460.04, "l": "That''s wild.", "sp": 2}, {"t": 460.9, "e": 467.88, "l": "Question ten from the multiple choice explains the underlying mechanism here. They actually breathe through gills, and they require moisture.", "sp": 1}, {"t": 468.02, "e": 469.8, "l": "That is why they reside in damp soil.", "sp": 1}, {"t": 470.38, "e": 473.46, "l": "Oh, so they aren''t insects at all, even though their appearance tricks us.", "sp": 2}, {"t": 473.64, "e": 484.34, "l": "No. The visual clues here are brilliant. For appearance, they show a male Armadillidium vulgare, a pill bug, and it looks like a tiny gray armored tank.", "sp": 1}, {"t": 484.82, "e": 493.6, "l": "But for species, they paired it with a photo of a painted ghost crab. It visually bridges that gap, showing you that this garden bug is actually a crustacean.", "sp": 2}, {"t": 494.18, "e": 501.52, "l": "Which is vital to their ecological role, bringing us to our next words, ecological, molting, and life-threatening.", "sp": 1}, {"t": 502.16, "e": 509.26, "l": "They serve a vital ecological function by recycling leaves. As they grow, they undergo molting, and dehydration is life-threatening to them.", "sp": 2}, {"t": 509.8, "e": 516.72, "l": "The word ecological comes from the Greek word oikos, meaning house. Ecology is literally the study of nature''s household.", "sp": 1}, {"t": 517.2, "e": 518.42, "l": "Every organism has a chore.", "sp": 1}, {"t": 519.12, "e": 525.34, "l": "Like cleaning up. Question nine tells us the pill bug''s ecological job is recycling decaying plant matter.", "sp": 2}, {"t": 525.62, "e": 534.1, "l": "Right. And the photo for ecological is this lush Thai forest floor covered in leaves, the perfect household for a decomposer.", "sp": 1}, {"t": 534.9, "e": 536.18, "l": "But what about molting?", "sp": 2}, {"t": 536.8, "e": 541.76, "l": "Well, since they are crustaceans, their skeleton is on the outside, an exoskeleton.", "sp": 1}, {"t": 542.38, "e": 543.36, "l": "Right, like armor.", "sp": 2}, {"t": 543.96, "e": 550.5, "l": "And armor doesn''t grow. So as the organism inside gets bigger, it has to burst out of its old armor and grow a new one.", "sp": 1}, {"t": 551.06, "e": 555.42, "l": "That shedding process is molting. Question twelve confirms this exact mechanism.", "sp": 1}, {"t": 555.76, "e": 562.34, "l": "The photo for molting is so cool. It''s a dragonfly right in the middle of metamorphosis, pulling itself out of its old skin.", "sp": 2}, {"t": 562.54, "e": 569.9, "l": "That''s a great visual. And finally, life-threatening. Because they have gills, drying out isn''t just uncomfortable.", "sp": 1}, {"t": 570.12, "e": 571.46, "l": "It will end their life.", "sp": 1}, {"t": 572.12, "e": 577.16, "l": "The worksheet uses a bright yellow danger sign to represent how serious life-threatening really is.", "sp": 2}, {"t": 578.12, "e": 583.5, "l": "So we have a crustacean completely disguised as a bug, living a kind of double life under the dirt.", "sp": 1}, {"t": 584.34, "e": 592.12, "l": "And speaking of living a double life, that idea connects us perfectly to our third story, the accountant who dreamed in poetry.", "sp": 2}, {"t": 592.72, "e": 599.76, "l": "We are looking at a real historical figure here, Walter de la Mare, and the words bookkeeper and monotonous.", "sp": 1}, {"t": 600.58, "e": 606.6, "l": "The sentence tells us Walter de la Mare worked as an office bookkeeper, which felt extremely monotonous.", "sp": 2}, {"t": 607.54, "e": 617.82, "l": "A bookkeeper is someone who maintains financial records for a business. It''s exact numerical work. And monotonous means lacking in variety, completely tedious.", "sp": 1}, {"t": 618.24, "e": 619.44, "l": "Like painfully boring.", "sp": 2}, {"t": 619.92, "e": 632.0, "l": "Exactly. If we break down monotonous, it makes sense. Mono means one, and tone means sound. Imagine hitting the exact same note on a piano over and over and over again.", "sp": 1}, {"t": 632.18, "e": 642.56, "l": "Ugh, that sounds awful. Question thirty-five links monotonous directly to writing endless numbers in ledgers, and question sixteen and seventeen reinforce that he was a corporate accountant.", "sp": 2}, {"t": 643.0, "e": 653.62, "l": "The visual clues sell the misery too. Bookkeeper is an old account ledger photo, and monotonous, the photo is literally called Boredom Man, just a guy bored out of his mind.", "sp": 1}, {"t": 654.42, "e": 660.64, "l": "Which is why he had to escape, and he did that through our next two words, pseudonym and published.", "sp": 2}, {"t": 661.0, "e": 661.28, "l": "Yes.", "sp": 1}, {"t": 661.76, "e": 669.12, "l": "He initially published his imaginative stories under a fictitious pseudonym. I love this. It''s like a superhero''s secret identity.", "sp": 2}, {"t": 669.42, "e": 669.78, "l": "What do you mean?", "sp": 1}, {"t": 670.28, "e": 678.38, "l": "It''s like Peter Parker working a totally monotonous day job just paying the bills, but secretly, under a different name, he''s doing something spectacular in the shadows.", "sp": 2}, {"t": 678.74, "e": 688.22, "l": "That is a perfect analogy. Pseudo means fake, and nym means name, a fake name to protect your creative identity from your corporate identity.", "sp": 1}, {"t": 688.72, "e": 692.44, "l": "Question thirty-seven defines this directly as a fictitious pen name.", "sp": 2}, {"t": 693.08, "e": 700.52, "l": "And published just means preparing and issuing that work for the public. The photo for published is a stack of Martin Newell''s poetry collections.", "sp": 1}, {"t": 700.94, "e": 706.48, "l": "And the photo for pseudonym is a portrait of Walter de la Mare himself, the man finally taking off the mask.", "sp": 2}, {"t": 706.8, "e": 712.5, "l": "He was able to take off that mask because of our next two words, pension and rejuvenated.", "sp": 1}, {"t": 713.0, "e": 717.26, "l": "A civil list government pension allowed him to quit and feel rejuvenated.", "sp": 2}, {"t": 717.88, "e": 725.3, "l": "A pension is a regular retirement payment. Question eighteen explicitly points out that receiving this government pension changed his life.", "sp": 1}, {"t": 726.12, "e": 727.4, "l": "It gave him financial freedom.", "sp": 1}, {"t": 728.06, "e": 730.18, "l": "And once he quit, he was rejuvenated.", "sp": 2}, {"t": 730.9, "e": 737.18, "l": "Let''s look at the roots. Re means again and juven means young. Think of the word juvenile.", "sp": 1}, {"t": 737.62, "e": 740.8, "l": "Oh, so it literally means restored to youth.", "sp": 2}, {"t": 741.24, "e": 751.9, "l": "Exactly. The pension gave him his youth back. The photo for pension is this sweet elderly couple, and rejuvenated is a refreshing, lush countryside landscape.", "sp": 1}, {"t": 751.98, "e": 754.2, "l": "You look at it and you just feel like you can breathe.", "sp": 1}, {"t": 754.98, "e": 761.48, "l": "But before he got that pension, he had to squeeze his writing in whenever he could, which usually meant deep into the night.", "sp": 2}, {"t": 762.4, "e": 764.04, "l": "When the rest of the world was asleep.", "sp": 1}, {"t": 764.6, "e": 773.76, "l": "Which transitions us beautifully into our final setting. The poet writing in the dark brings us to a quiet moonlit farm to explore nocturnal life.", "sp": 2}, {"t": 774.3, "e": 778.9, "l": "Our first three words here are nocturnal, couched, and kennel.", "sp": 1}, {"t": 779.58, "e": 785.14, "l": "The sentence says, \"Owls are nocturnal, while a loyal watchdog slumbered, couched inside his kennel.\"", "sp": 2}, {"t": 786.12, "e": 792.2, "l": "Nocturnal comes from the Latin word nox, meaning night, and simply means being active at night instead of the day.", "sp": 1}, {"t": 792.84, "e": 795.9, "l": "Multiple choice question thirty-three confirms owls hunt in darkness.", "sp": 1}, {"t": 796.6, "e": 800.44, "l": "And a kennel is a shelter built for a dog. But I have a question about the word couched.", "sp": 2}, {"t": 801.06, "e": 801.48, "l": "Sure. What''s up?", "sp": 1}, {"t": 802.22, "e": 812.92, "l": "The text says the dog was couched like a log. W- we usually sit on a couch in our living room. Does couched just mean you''re molded into your resting spot so perfectly you look like a piece of furniture?", "sp": 2}, {"t": 813.76, "e": 824.28, "l": "You''re actually right on the money. It comes from the French word coucher, which means to lie down deeply. When the dog is couched, he isn''t just sitting, he is completely, heavily resting.", "sp": 1}, {"t": 824.9, "e": 828.86, "l": "Question fifty-two actually features that simile, right? Couched like a log in his kennel.", "sp": 2}, {"t": 829.5, "e": 838.26, "l": "Yep, emphasizing that immovable rest. The visual clues are so cozy too. Uh, for nocturnal, we get this photo of a Eurasian eagle owl.", "sp": 1}, {"t": 838.92, "e": 840.72, "l": "Kennel is a classic doghouse.", "sp": 1}, {"t": 841.1, "e": 846.34, "l": "And couched is this photo of a white dog sleeping on the floor with little puppies just perfectly at rest.", "sp": 2}, {"t": 846.92, "e": 852.28, "l": "But while the dog is safely couched, other things are moving. We have shadowy and scampering.", "sp": 1}, {"t": 852.76, "e": 856.44, "l": "A tiny gray rodent went scampering through the shadowy corners of the barn.", "sp": 2}, {"t": 856.94, "e": 864.84, "l": "Shadowy means dim and faintly visible, full of shadows. But think about the word scampering. Notice how the word itself sounds fast and light?", "sp": 1}, {"t": 864.9, "e": 865.62, "l": "Yeah, scamper.", "sp": 2}, {"t": 865.88, "e": 868.06, "l": "It means running with quick light steps.", "sp": 1}, {"t": 868.66, "e": 875.72, "l": "The photo for shadowy is this dark chicken coop window, and scampering is just a little mouse on a white background.", "sp": 2}, {"t": 876.62, "e": 879.8, "l": "You can almost hear those tiny claws going ticka-ticka-ticka across the barn floor.", "sp": 2}, {"t": 880.48, "e": 887.14, "l": "Which pulls us back for a wide shot of the entire scene with our final three words, harvest, gleam, and reeds.", "sp": 1}, {"t": 887.9, "e": 896.74, "l": "The sentence paints such a quiet picture. The full moon shone over autumn harvest fields, casting a silvery gleam on the water reeds.", "sp": 2}, {"t": 897.4, "e": 907.36, "l": "A harvest is the gathering of mature crops. A gleam is a faint, brief shine of reflected light. And reeds are those tall, feathery grasses that grow right on the water''s edge.", "sp": 1}, {"t": 908.1, "e": 912.16, "l": "Question nineteen highlights the silvery moonlight setting the scene for that gleam.", "sp": 2}, {"t": 912.58, "e": 919.74, "l": "And the photo clues wrap this up perfectly. Harvest is a combine harvester in the wheat. Gleam is the glowing River Thames.", "sp": 1}, {"t": 920.2, "e": 923.72, "l": "And reeds are those tall feather-like grasses swaying in the dark.", "sp": 1}, {"t": 924.24, "e": 929.58, "l": "So if we step back and look at what we''ve done today, vocabulary isn''t just a list of words to memorize for a test.", "sp": 2}, {"t": 929.82, "e": 934.0, "l": "Not at all. By using these sources, we brewed tea with an ailing emperor.", "sp": 1}, {"t": 934.28, "e": 936.24, "l": "We dug in the dirt with molting pill bugs.", "sp": 2}, {"t": 936.58, "e": 938.68, "l": "We uncovered a poet''s secret pseudonym.", "sp": 1}, {"t": 939.12, "e": 945.86, "l": "And we tiptoed past a couched dog in the moonlight. We''ve seen exactly how these words paint vivid pictures.", "sp": 2}, {"t": 946.72, "e": 950.3, "l": "If you''re that fifth grader listening, these words are now tools in your own toolbox.", "sp": 1}, {"t": 950.46, "e": 960.2, "l": "Yes. The next time you write a story, instead of saying someone was tired, you can say they were lethargic. Instead of saying a potion tasted bad, you can call it unpalatable.", "sp": 2}, {"t": 960.96, "e": 964.12, "l": "You aren''t just telling a story anymore, you''re building an experience.", "sp": 1}, {"t": 964.4, "e": 964.94, "l": "I love that.", "sp": 2}, {"t": 965.18, "e": 974.78, "l": "And here''s one last thing to think about. We saw today how the word tea came from a distant ancient Chinese palace and eventually landed in our modern kitchens as an everyday beverage.", "sp": 1}, {"t": 974.88, "e": 975.02, "l": "Right.", "sp": 2}, {"t": 975.56, "e": 977.76, "l": "Words travel through time just like objects do.", "sp": 1}, {"t": 978.08, "e": 986.06, "l": "So true. I wonder which of the new words you mastered today is gonna travel with you into the next story you read or write, and how its meaning might grow and change just for you.", "sp": 2}, {"t": 986.54, "e": 987.6, "l": "The words are waiting for you.", "sp": 1}, {"t": 988.48, "e": 991.56, "l": "Keep reading, keep exploring, and we''ll see you on the next deep dive.", "sp": 2}]'::jsonb, 100)
on conflict (id) do update set unit = excluded.unit, also_units = excluded.also_units, kind = excluded.kind, title = excluded.title,
  media_url = excluded.media_url, lines = excluded.lines, position = excluded.position;

select kind, unit, also_units, title, jsonb_array_length(lines) as lines from public.set_songs where kind = 'dialog';
